begin;
create schema vt;
create function vt.ok(v boolean,label text) returns void language plpgsql as $$ begin if v is distinct from true then raise exception 'ASSERT %',label;end if;end $$;
create function vt.no(cmd text,label text) returns void language plpgsql as $$ begin begin execute cmd;exception when others then return;end;raise exception 'ACCEPTED %',label;end $$;
grant usage on schema vt to authenticated,service_role;grant execute on all functions in schema vt to authenticated,service_role;
