-- Reliable installation boundary distinguishes unknown historical counts from observed zeros.
select set_config('vt.tracking_start',(select started_at::text from marketing_private.report_tracking),true);
select vt.ok(not has_table_privilege('authenticated','marketing_private.report_tracking','select') and not has_table_privilege('service_role','marketing_private.report_tracking','update'),'tracking boundary private and not client configurable');
select vt.no($q$update marketing_private.report_tracking set started_at='2020-01-01'$q$,'tracking boundary immutable');
select vt.ok((current_setting('vt.empty')::jsonb#>>'{metrics,coverage,production_tracking_started_at}')::timestamptz=current_setting('vt.tracking_start')::timestamptz,'snapshot freezes actual installation boundary');
-- Superuser-only fixture simulation of a database installed before the report's period.
alter table marketing_private.report_tracking disable trigger report_tracking_immutable;
update marketing_private.report_tracking set started_at='2026-09-01T00:00:00+07:00';
alter table marketing_private.report_tracking enable trigger report_tracking_immutable;
